import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] a = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken()) % m;
        }
        Set<Integer> x = new HashSet<>();
        Set<Integer> y = new HashSet<>();

        f(x, a, 0, n / 2, 0, m);
        f(y, a, n / 2, n, 0, m);

        List<Integer> yList = new ArrayList<>(y);
        Collections.sort(yList);

        int maxSum = 0;
        for (int i : x) {
            int target = m - i;
            int idx = Collections.binarySearch(yList, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                int candidate = i + yList.get(idx - 1);
                if (candidate > maxSum && candidate < m) {
                    maxSum = candidate;
                }
            }
        }
        System.out.println(maxSum);
    }

    private static void f(Set<Integer> set, int[] a, int start, int end, int s, int m) {
        if (start == end) {
            set.add(s % m);
        } else {
            f(set, a, start + 1, end, (s + a[start]) % m, m);
            f(set, a, start + 1, end, s, m);
        }
    }
}
